-- ============================================================
--  Sistema de Gestión de Documentos de una Oficina
--  Desarrollo de Aplicaciones Web y Móviles · UNACH
--
--  Script de creación de la base de datos y datos de prueba.
--  Se importa desde phpMyAdmin (pestaña «Importar») o con:
--
--      /Applications/XAMPP/xamppfiles/bin/mysql -u root < gestion_documentos.sql
--
--  El mismo script se usa para la base en la nube que consume
--  la versión publicada en Vercel.
--
--  OJO: borra y vuelve a crear la base «gestion_documentos».
-- ============================================================

-- Las horas de los datos de prueba están en hora del centro de México;
-- así se guardan bien aunque el servidor MySQL esté en otra zona horaria.
SET time_zone = '-06:00';

DROP DATABASE IF EXISTS gestion_documentos;

CREATE DATABASE gestion_documentos
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_spanish_ci;

USE gestion_documentos;

-- ------------------------------------------------------------
--  Tabla principal: un renglón por documento recibido.
-- ------------------------------------------------------------
CREATE TABLE documentos (
    id_documento   INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    no_oficio      VARCHAR(30)   NOT NULL,
    fecha          DATE          NOT NULL COMMENT 'Fecha de recepción',
    asunto         VARCHAR(200)  NOT NULL,
    remitente      VARCHAR(150)  NOT NULL,
    destinatario   VARCHAR(150)  NOT NULL,
    estatus        ENUM('Recibido', 'En proceso', 'Atendido') NOT NULL DEFAULT 'Recibido',
    archivo_pdf    VARCHAR(255)  NULL     COMMENT 'Nombre del PDF digitalizado (el contenido está en archivos_pdf)',
    creado_en      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    actualizado_en TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (id_documento),

    -- Dos documentos no pueden compartir número de oficio.
    UNIQUE KEY uq_no_oficio (no_oficio),

    -- Índices para los filtros del listado.
    KEY idx_fecha          (fecha),
    KEY idx_estatus_fecha  (estatus, fecha),
    KEY idx_remitente      (remitente),
    KEY idx_destinatario   (destinatario)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

-- ------------------------------------------------------------
--  Bitácora de estatus: guarda cada cambio para dar seguimiento.
--  Si se elimina el documento, se borra también su historial.
-- ------------------------------------------------------------
CREATE TABLE bitacora_estatus (
    id_bitacora      INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_documento     INT UNSIGNED NOT NULL,
    estatus_anterior ENUM('Recibido', 'En proceso', 'Atendido') NULL COMMENT 'NULL cuando es el registro inicial',
    estatus_nuevo    ENUM('Recibido', 'En proceso', 'Atendido') NOT NULL,
    fecha_cambio     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id_bitacora),
    KEY idx_documento_fecha (id_documento, fecha_cambio),

    CONSTRAINT fk_bitacora_documento
        FOREIGN KEY (id_documento) REFERENCES documentos (id_documento)
        ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;

-- ------------------------------------------------------------
--  Contenido de los PDF digitalizados, uno por documento.
--  Va en una tabla aparte para que el listado (que consulta
--  «documentos» muchas veces) no cargue los archivos.
--  Se guardan en la base y no en una carpeta porque en Vercel el
--  disco del servidor no es permanente.
--  MEDIUMBLOB admite hasta 16 MB; la aplicación limita a 4 MB.
-- ------------------------------------------------------------
CREATE TABLE archivos_pdf (
    id_documento INT UNSIGNED NOT NULL,
    contenido    MEDIUMBLOB   NOT NULL,
    tamano       INT UNSIGNED NOT NULL COMMENT 'Bytes',

    PRIMARY KEY (id_documento),

    CONSTRAINT fk_archivo_documento
        FOREIGN KEY (id_documento) REFERENCES documentos (id_documento)
        ON DELETE CASCADE
) ENGINE=InnoDB;

